import{_ as o,o as r,c as e,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-11-09","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-11-09","date":"2021-11-09T00:00:00.000Z","updated":"2021-11-10T00:00:00.000Z","tags":["Ceph","会议纪要","分布式存储","开发环境","配置文件","控制台"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-11-09.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-11-09.md","lastUpdated":1780459816000}'),n={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-11-09.md"};function a(s,t,i,g,h,d){return r(),e("div",null,[...t[0]||(t[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>会议类型</strong>: 每周协调会议</li><li><strong>日期</strong>: 2021年11月9日</li><li><strong>参会人员</strong>: [列出参会人员]</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Topo LVM 更新</strong></p><ul><li><strong>讨论内容</strong>: Travis、Seb 和 Joseph 讨论了 Topo LVM 处理原始设备的能力。</li><li><strong>结论</strong>: Topo LVM 目前无法处理原始设备，需要大量设计和投资。OCS 目前使用 LSO 处理静态卷和原始卷，而 Topo LVM 处理本地存储的动态供应。</li><li><strong>后续行动</strong>: 继续使用现有解决方案，不急于推动 Topo LVM 更新。</li></ul></li><li><p><strong>Docker 开发环境</strong></p><ul><li><strong>讨论内容</strong>: 讨论了添加 Docker 开发环境的 Pull Request。</li><li><strong>反馈</strong>: 需要找到更清洁的方式在本地回环设备上创建 OSDs。</li><li><strong>进展</strong>: Docker 开发环境已经可以运行，但需要解决 NFS 服务部署时的错误。</li></ul></li><li><p><strong>CentOS Stream 和 Podman</strong></p><ul><li><strong>讨论内容</strong>: 讨论了使用 CentOS Stream 和 Podman 的问题。</li><li><strong>进展</strong>: 目前使用 CentOS Stream 作为临时解决方案，需要持续跟进 Podman 的修复。</li></ul></li><li><p><strong>Ceph 配置文件路径变更</strong></p><ul><li><strong>讨论内容</strong>: 讨论了将 Ceph 配置文件路径从 <code>user</code> 更改为 <code>/etc</code> 的 Pull Request。</li><li><strong>结论</strong>: 需要处理路径迁移问题，其他方面没有大问题。</li></ul></li><li><p><strong>使用控制台作为 IGW 前端</strong></p><ul><li><strong>讨论内容</strong>: 讨论了使用控制台作为 IGW 前端的可行性。</li><li><strong>结论</strong>: 需要手动部署 HAProxy，控制台可以作为替代方案。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>Topo LVM</strong>: 继续使用现有解决方案，不急于推动更新。</li><li><strong>Docker 开发环境</strong>: 需要找到更清洁的方式创建 OSDs。</li><li><strong>CentOS Stream 和 Podman</strong>: 继续使用 CentOS Stream，持续跟进 Podman 的修复。</li><li><strong>Ceph 配置文件路径</strong>: 处理路径迁移问题。</li><li><strong>控制台作为 IGW 前端</strong>: 需要手动部署 HAProxy。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>Topo LVM</strong>: 继续监控现有解决方案的性能和稳定性。</li><li><strong>Docker 开发环境</strong>: 解决 NFS 服务部署错误，优化 OSD 创建方式。</li><li><strong>CentOS Stream 和 Podman</strong>: 持续跟进 Podman 的修复，确保稳定版本可用。</li><li><strong>Ceph 配置文件路径</strong>: 完成路径迁移，确保配置文件的正确性。</li><li><strong>控制台作为 IGW 前端</strong>: 测试控制台作为 IGW 前端的可行性，确保部署流程的顺畅。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>Dashboard 团队的工作</strong>: 他们的工作已经合并到 Pacific 分支，需要关注后续的测试和反馈。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li><strong>下次会议</strong>: 下周同一时间</li><li><strong>结束语</strong>: 祝大家周二愉快，下次会议再见。</li></ul>',13)])])}const u=o(n,[["render",a]]);export{p as __pageData,u as default};
